public int minPathSum(int[][] grid) {
    return cost(grid, 0, 0);
}

private int cost(int[][] grid, int i, int j) {
    int m = grid.length, n = grid[0].length;
    if (i >= m || j >= n) {
        return Integer.MAX_VALUE;
    }
    if (i == m - 1 && j == n - 1) {
        return grid[i][j];
    }
    int down = cost(grid, i + 1, j);
    int right = cost(grid, i, j + 1);
    return grid[i][j] + Math.min(down, right);
}

