def minPathSum(self, grid: list[list[int]]) -> int:
    m, n = len(grid), len(grid[0])

    def cost(i: int, j: int) -> int:
        if i >= m or j >= n:
            return float('inf')
        if i == m - 1 and j == n - 1:
            return grid[i][j]
        return grid[i][j] + min(cost(i + 1, j), cost(i, j + 1))

    return cost(0, 0)

